  "hypothesis": "Replacing the five fixed mixture weights with an adaptive active-peak line search will detect narrow improving mixtures missed by the parent and yield a verified gain of at least 1e-8.",
  "rationale": "The parent tests only five mixture weights, although the maximum-convolution denominator can create narrow optima near changes of the active peak. The revised search retains packet remeshing but optimizes the exact quartic numerator against an adaptively enlarged set of denominator peaks, then verifies every accepted candidate with the frozen formula.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'proposals': (24, 6, 64),
    'width_step': (1.0, 0.25, 8.0),
    'reserve': (0.70, 0.5, 0.75)
}

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['reserve']) * budget_s
    rng = np.random.default_rng(seed)
    def alive(margin=0.0):
        return time.monotonic() + margin < deadline
    def exact(f):
        z = np.maximum(f, 0.0)
        c = oaconvolve(z, z, mode='full')
        m = len(c)
        dx = np.diff(np.linspace(-0.5, 0.5, m + 2))
        y = np.concatenate(([0.0], c, [0.0]))
        num = float(np.sum((dx / 3.0) * (y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)))
        return num / ((np.sum(np.abs(c))/(m+1))*np.max(np.abs(c)))
    def fast_score(c):
        return float((2*np.dot(c,c)+np.dot(c[:-1],c[1:])) / (3*np.sum(np.abs(c))*np.max(np.abs(c))))
    if init is None:
        return {'length': 1, 'packets': [[0, [1.0]]]}
    if 'values' in init:
        raw = init['values']
    else:
        raw = np.zeros(int(init['length']))
        for a, v in init['packets']:
            if not alive(3):
                return init
            raw[int(a):int(a)+len(v)] += np.asarray(v)
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    baseline = exact(f)
    if not alive(5) or len(f) < 4:
        return init
    n = len(f)
    f = f / np.max(f)
    edges = np.diff(np.r_[False, f > 0, False].astype(np.int8))
    aa = np.flatnonzero(edges == 1)
    bb = np.flatnonzero(edges == -1)
    if len(aa) < 2:
        return init
    mass = np.r_[0.0, np.cumsum(f)]
    heavy = int(np.argmax(mass[bb]-mass[aa]))
    prefixes = []
    for a,b in zip(aa,bb):
        if not alive(5):
            return init
        prefixes.append(np.r_[0.0, np.cumsum(f[a:b])])
    nc = 2*n-1
    L = next_fast_len(nc)
    F = rfft(f,L,workers=1)
    c = irfft(F*F,L,workers=1)[:nc]
    best_score = baseline
    best = None
    step = float(params['width_step'])
    specs = []
    for delta in (step, -step, 2*step, -2*step, 4*step, -4*step):
        for anchor in (0.5, 0.0, 1.0):
            if not alive(4):
                return init
            specs.append((delta, anchor, 0))
    specs += [(step,0.5,1),(-step,0.5,1),(2*step,0.5,2),(-2*step,0.5,2),(.20,0.5,3),(-.20,0.5,3)]
    for j in range(max(0,int(params['proposals'])-len(specs))):
        if not alive(5):
            break
        specs.append((float(rng.choice([-1,1]))*step*float(rng.uniform(.5,5)), float(rng.choice([0,.5,1])), int(rng.integers(0,3))))

    # The numerator is quartic in the mixture weight. Only the active
    # convolution peaks are needed for its piecewise-quadratic denominator.
    cnum = 2*np.dot(c,c)+np.dot(c[:-1],c[1:])
    def mixture_search(cd, dd):
        vectors = (c, cd, dd)
        coef = np.zeros(5)
        for i in range(3):
            for j in range(3):
                if not alive(3):
                    return None
                if i == 0 and j == 0:
                    coef[0] = cnum
                else:
                    coef[i+j] += 2*np.dot(vectors[i],vectors[j]) + np.dot(vectors[i][:-1],vectors[j][1:])
        sums = np.array([np.sum(c),np.sum(cd),np.sum(dd)])
        peaks = {int(np.argmax(c))}
        for a in (0.0078125,0.03125,0.125,0.5,1.0):
            if not alive(3):
                return None
            v = c+a*cd+a*a*dd
            peaks.add(int(np.argmax(v)))
        grid = np.unique(np.r_[0.0, np.geomspace(1e-9,1.0,100), np.linspace(0,1,81)])
        winner = None
        winner_score = best_score
        for iteration in range(5):
            if not alive(3):
                break
            ix = np.fromiter(sorted(peaks),dtype=np.int64)
            u,v,w = c[ix],cd[ix],dd[ix]
            def objective(a):
                den = 3.0*np.polynomial.polynomial.polyval(a,sums)*np.max(u+a*v+a*a*w)
                return -float(np.polynomial.polynomial.polyval(a,coef)/den)
            scores = []
            for a in grid:
                if not alive(3):
                    return winner
                scores.append(objective(float(a)))
            k = int(np.argmin(scores))
            alpha = float(grid[k])
            if 0 < k < len(grid)-1:
                def guarded(a):
                    if not alive(3):
                        return 1e10
                    return objective(a)
                res = minimize_scalar(guarded,bounds=(float(grid[k-1]),float(grid[k+1])),method='bounded',options={'xatol':1e-12,'maxiter':45})
                if res.fun < scores[k]:
                    alpha = float(res.x)
            if not alive(3):
                break
            cc = c+alpha*cd+alpha*alpha*dd
            score = fast_score(cc)
            if alpha > 0 and score > winner_score + 2e-13:
                winner, winner_score = alpha, score
            active = int(np.argmax(cc))
            if active in peaks:
                break
            peaks.add(active)
        return winner

    for delta,anchor,mode in specs[:int(params['proposals'])]:
        if not alive(5):
            break
        g = np.zeros(n,dtype=np.float64)
        complete = True
        for j,(a,b) in enumerate(zip(aa,bb)):
            if not alive(4):
                complete = False
                break
            a,b = int(a),int(b)
            w = b-a
            if j == heavy:
                g[a:b] += f[a:b]
                continue
            x = (a+b)/(2.0*n)
            if mode == 1:
                change = delta*(2*x-1)
            elif mode == 2:
                change = delta*np.cos(2*np.pi*x)
            elif mode == 3:
                change = delta*w
            else:
                change = delta
            new_w = max(0.25,w+change)
            left = a-anchor*(new_w-w)
            right = left+new_w
            if left < 0:
                right -= left
                left = 0.0
            if right > n:
                left -= right-n
                right = float(n)
            left = max(0.0,left)
            actual = right-left
            if actual <= 0:
                complete = False
                break
            lo = max(0,int(np.floor(left)))
            hi = min(n,int(np.ceil(right)))
            boundaries = np.arange(lo,hi+1,dtype=np.float64)
            old_coordinate = np.clip((boundaries-left)*(w/actual),0.0,float(w))
            ix = np.minimum(np.floor(old_coordinate).astype(np.int64),w-1)
            integral = prefixes[j][ix] + (old_coordinate-ix)*f[a+ix]
            g[lo:hi] += np.maximum(np.diff(integral),0.0)
        if not complete or not alive(4):
            break
        d = g-f
        D = rfft(d,L,workers=1)
        cd = 2*irfft(F*D,L,workers=1)[:nc]
        dd = irfft(D*D,L,workers=1)[:nc]
        winner = mixture_search(cd,dd)
        if winner is not None and alive(2.5):
            proposal = np.maximum(f+winner*d,0.0)
            verified = exact(proposal)
            if verified > best_score:
                best_score = verified
                best = proposal
    if best is None:
        return init
    transitions = np.diff(np.r_[False,best > 0,False].astype(np.int8))
    starts = np.flatnonzero(transitions == 1)
    stops = np.flatnonzero(transitions == -1)
    packets = []
    for a,b in zip(starts,stops):
        if time.monotonic() > start + .90*budget_s:
            return init
        packets.append([int(a),best[a:b].tolist()])
    return {'length': n, 'packets': packets}
